CREATE TABLE IF NOT EXISTS support_tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_number VARCHAR(40) NOT NULL UNIQUE,client_id BIGINT UNSIGNED NULL,project_id BIGINT UNSIGNED NULL,assigned_staff_id BIGINT UNSIGNED NULL,subject VARCHAR(255) NOT NULL,description TEXT NULL,category VARCHAR(100) NULL,priority ENUM('low','medium','high','urgent') NOT NULL DEFAULT 'medium',status ENUM('open','in_progress','waiting_client','resolved','closed') NOT NULL DEFAULT 'open',opened_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,first_response_at DATETIME NULL,resolved_at DATETIME NULL,closed_at DATETIME NULL,due_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_ticket_client(client_id),INDEX idx_ticket_project(project_id),INDEX idx_ticket_staff(assigned_staff_id),INDEX idx_ticket_status(status),CONSTRAINT fk_ticket_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL,CONSTRAINT fk_ticket_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE SET NULL,CONSTRAINT fk_ticket_staff FOREIGN KEY(assigned_staff_id) REFERENCES staff_members(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS support_sla_policies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,priority ENUM('low','medium','high','urgent') NOT NULL UNIQUE,first_response_minutes INT UNSIGNED NOT NULL,resolution_minutes INT UNSIGNED NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO support_sla_policies(name,priority,first_response_minutes,resolution_minutes) VALUES ('Standard Low','low',1440,4320),('Standard Medium','medium',480,2880),('Priority High','high',120,1440),('Critical Urgent','urgent',30,480);
CREATE TABLE IF NOT EXISTS client_communications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id BIGINT UNSIGNED NULL,project_id BIGINT UNSIGNED NULL,ticket_id BIGINT UNSIGNED NULL,staff_id BIGINT UNSIGNED NULL,channel ENUM('email','phone','whatsapp','meeting','portal','internal') NOT NULL,subject VARCHAR(255) NULL,message TEXT NULL,direction ENUM('inbound','outbound','internal') NOT NULL DEFAULT 'outbound',occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_comm_client(client_id),INDEX idx_comm_project(project_id),INDEX idx_comm_ticket(ticket_id),CONSTRAINT fk_comm_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL,CONSTRAINT fk_comm_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE SET NULL,CONSTRAINT fk_comm_ticket FOREIGN KEY(ticket_id) REFERENCES support_tickets(id) ON DELETE SET NULL,CONSTRAINT fk_comm_staff FOREIGN KEY(staff_id) REFERENCES staff_members(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS client_success_profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id BIGINT UNSIGNED NOT NULL UNIQUE,health ENUM('healthy','at_risk','critical') NOT NULL DEFAULT 'healthy',satisfaction_score DECIMAL(5,2) NULL,renewal_date DATE NULL,renewal_value DECIMAL(15,2) NULL,success_owner_id BIGINT UNSIGNED NULL,risk_notes TEXT NULL,goals TEXT NULL,last_reviewed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_success_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE CASCADE,CONSTRAINT fk_success_owner FOREIGN KEY(success_owner_id) REFERENCES staff_members(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS client_success_activities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,profile_id BIGINT UNSIGNED NOT NULL,staff_id BIGINT UNSIGNED NULL,type ENUM('review','follow_up','risk','renewal','feedback','meeting') NOT NULL,message TEXT NOT NULL,due_date DATE NULL,completed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_success_activity_profile(profile_id),CONSTRAINT fk_success_activity_profile FOREIGN KEY(profile_id) REFERENCES client_success_profiles(id) ON DELETE CASCADE,CONSTRAINT fk_success_activity_staff FOREIGN KEY(staff_id) REFERENCES staff_members(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS operations_notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type VARCHAR(80) NOT NULL,recipient_staff_id BIGINT UNSIGNED NULL,client_id BIGINT UNSIGNED NULL,title VARCHAR(255) NOT NULL,message TEXT NULL,reference_type VARCHAR(80) NULL,reference_id BIGINT UNSIGNED NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_notification_recipient(recipient_staff_id),INDEX idx_notification_unread(read_at),CONSTRAINT fk_notification_staff FOREIGN KEY(recipient_staff_id) REFERENCES staff_members(id) ON DELETE SET NULL,CONSTRAINT fk_notification_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;